export const EVENT_TEMPLATES=Object.entries(STORIES).flatMap(([family,rows])=>rows.map(([title,scene,job],i)=>{const j=JOBS[job],steps=PLANS[job]||[step(j.start,j.working,j.hours)],hours=steps.reduce((n,p)=>n+p.hours,0);return {id:family+'-'+i,family,title,scene,job,tone:bad.has(family)?'bad':'good',...j,steps,hours,guest:!!j.guest,rareGuest:!!j.guest,reward:140+hours*25+(bad.has(family)?30:0)+(i%5)*10};}));
export const EVENT_CATALOG=EVENT_TEMPLATES.flatMap(t=>Object.keys(SPECIES).map(species=>({...t,key:t.id+':'+species,species})));
export const EVENT_BY_KEY=Object.fromEntries(EVENT_CATALOG.map(t=>[t.key,t]));
